-- OPS-FAILOVER-1 (2026-11-05, charter pillars autonomy and security; roadmap row RM-S1-REDUNDANCY-1 id 5, VSM S1 "no redundancy / single ops gateway"; sub-agent c5-resilience of the owner request "CODE, DEPLOY, AND CLOSE ALL OPEN ROADMAP AND BACKLOG TASKS").
-- WHAT WAS TRUE (read 2026-11-05 ~00:00Z): the qnfo-ops worker answers on two hostnames, the custom domain https://ops.qnfo.org and the workers.dev host https://qnfo-ops.q08.workers.dev (workers_dev = true in qnfo-ops/wrangler.toml, added 2026-09-30); both returned HTTP 200 on /health,
-- /v1/models and /openapi.json at the same version 2.63.0-tool-arg-alias. Nothing measured the second hostname: a Worker cannot fetch its own account workers.dev hosts (Cloudflare error 1042), so the fleet could not test it from inside, and the Access application and WAF rules planned
-- for ops.qnfo.org (docs/CF-ACCESS-ROLLOUT-1277.md, RM-WAF-RATE-LIMIT-1) are exactly the faults that would cut the first hostname off while the worker is healthy. /health and /v1/models read no D1 (qnfo-ops/worker.js route /health), so they are the part that must keep answering while qnfo-audit is overloaded.
-- WHAT THIS DOES: registers ops_gateway_hosts_ok (guard, target 1) measured hourly by scripts/bp26_opsfailover.py from the GitHub runner (the remediation-consumer job): the share of the two hostnames that answer both /health (status ok, worker qnfo-ops, a version) and /v1/models (the model id ops), one retry per failing request,
-- 0 only when a control worker proves the account is reachable. Adds its trigger (< 1) and cause. Files the next slice of the row as a ROADMAP-1 issue with a doer: the read-only degraded mode of qnfo-ops itself while qnfo-audit D1 is overloaded (qnfo-ops/worker.js is under another session claim, C-ops-tools, so no edit is made to it here).
-- Row 5 stays partial: the failover hostname is now measured; the degraded mode is not built. The spof_registry row and its enabled spof_alternate_probes row for the gateway host are added by a follow-up migration after the first runner reading (an alternate that has not been read yet must not be registered as tested).
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: DELETE FROM analytics_metric_triggers WHERE metric_key = 'ops_gateway_hosts_ok'; DELETE FROM metric_breach_cause WHERE metric_key = 'ops_gateway_hosts_ok'; DELETE FROM metric_registry WHERE metric = 'ops_gateway_hosts_ok'; DELETE FROM agent_issues WHERE source = 'session:c5-resilience' AND title LIKE 'ROADMAP-1: QNFO.OPS OPS-DEGRADED-1:%'; UPDATE roadmap_implementation SET evidence = substr(evidence, 1, instr(evidence, ' || C5-RESILIENCE-5 ') - 1) WHERE id = 5 AND instr(evidence, ' || C5-RESILIENCE-5 ') > 0;
-- BACKUP: agent_issues

INSERT OR IGNORE INTO metric_registry (metric, layer, kind, formula, source_of_truth, baseline, target, owner, disposition_actor, refresh_cadence, warning_band, kill_band, state, refresh_class)
VALUES ('ops_gateway_hosts_ok', 'operational', 'guard',
  'Share of the two hostnames that serve the qnfo-ops worker (https://ops.qnfo.org and https://qnfo-ops.q08.workers.dev) that answer both GET /health (HTTP 200, status ok, worker qnfo-ops, a version) and GET /v1/models (HTTP 200, the model id ops), read hourly from the GitHub runner with one retry per failing request. 1 = both hostnames serve the gateway, 0.5 = one does, 0 = neither does while a control worker answers; unknown (nothing written) when the runner cannot reach the account. The hostnames serving different versions is recorded in the evidence rows and does not lower the value.',
  'scripts/bp26_opsfailover.py collect_ops_failover: GET /health and /v1/models on each of the two qnfo-ops hostnames from the remediation-consumer runner, outside the Cloudflare account; one row per hostname in bp26_probe_results [BP26]',
  '1.0 on 2026-11-05 (both hostnames served 2.63.0-tool-arg-alias, 190 ms and 140 ms)', '1',
  'program-manager:QNFO.OPS', 'agent_issues predicate OPS-FAILOVER (doer: program-manager:QNFO.OPS)', '1h', 'lt 1', NULL, 'UNMEASURED', NULL);

INSERT INTO analytics_metric_triggers (metric_key, title, source_table, operator, threshold, priority, action, owner, queue_target, cooldown_hours, enabled, notes)
SELECT 'ops_gateway_hosts_ok', 'OPS-FAILOVER-1 ops_gateway_hosts_ok below 1', 'registry', 'lt', 1, 2,
  'Pillar autonomy (roadmap row RM-S1-REDUNDANCY-1). At least one of the two qnfo-ops hostnames did not serve the gateway at the last hourly read (retried once). Lever: read bp26_probe_results for this metric (the row names the hostname, the route and the HTTP status). If the alternate workers.dev host is the one down, check workers_dev = true in qnfo-ops/wrangler.toml and a deploy that dropped it; if ops.qnfo.org is down while the alternate answers, look at the zone first (a WAF rule, an Access application, the custom domain attachment) before the worker, and use the alternate host to reach the gateway meanwhile. Do not remove a hostname from scripts/bp26_opsfailover.py to make the value rise. Definition of done: the metric reads 1 at two consecutive refreshes.',
  'program-manager:QNFO.OPS', 'agent_issues', 4, 1, 'OPS-FAILOVER-1 (migrations/2026-11-04-c5-resilience-ops-failover.sql)'
WHERE NOT EXISTS (SELECT 1 FROM analytics_metric_triggers x WHERE x.metric_key = 'ops_gateway_hosts_ok');

INSERT OR IGNORE INTO metric_breach_cause (metric_key, cause_key, note) VALUES
  ('ops_gateway_hosts_ok', 'heartbeat', 'METRIC-CAUSE-AT-REGISTRATION-1 2026-11-05: a gateway hostname that stops answering is an availability fault of the route or the zone, the same cause class as the other liveness metrics, not spend, backlog or a defect in the measurement.');

INSERT INTO agent_issues (title, description, source, category, priority, status, created_at, updated_at)
SELECT 'ROADMAP-1: QNFO.OPS OPS-DEGRADED-1: qnfo-ops read-only degraded mode while the qnfo-audit D1 is overloaded',
 'QNFO.OPS; charter pillar autonomy; roadmap row RM-S1-REDUNDANCY-1 (second half: the read-only degraded mode); the existing metric ops_gateway_hosts_ok is the guard that the hostnames keep answering. Read 2026-11-05: qnfo-ops is the sole server-side executor and every tool that touches qnfo-audit fails partway when D1 answers "D1 DB is overloaded" (spof_registry records a 345 M rows read fleet_tick fan-out in 24 h on 2026-11-04, and qnfo-model-eval POST /run answered 500 with that text at 2026-11-04T23:04Z). /health and /v1/models read no D1 and keep answering (measured hourly by scripts/bp26_opsfailover.py), but nothing tells a caller that the gateway is degraded and the D1-writing tools refuse late and inconsistently. Work in qnfo-ops/worker.js: (1) a small in-isolate circuit breaker fed by the D1 error text qnfo-ops already classifies (/overloaded|too many resources|rate limit|timed out/i, see the EDC-BATCH-1 code): after 3 such errors in 60 s the gateway is degraded for 60 s; (2) while degraded, execTool refuses the tools that write qnfo-audit (ops_d1_write, ops_issue_run and the other tools that write qnfo-audit) with HTTP 503, Retry-After and {"degraded":true,"d1":"overloaded","retry_after_s":N} before they start, and keeps every tool that does not need D1 (cf_* calls, r2_*, kv_*, fleet probes, git and workspace tools, the /ops/deploy content PUT) available; (3) /health gains a degraded block with the breaker state and since; (4) a test that does not depend on live state (a fake D1 that throws the overload text three times, the refusal, the recovery after the window, and a D1-free tool still running). Run fleet-graph impact on fn:qnfo-ops#execTool and on the 9 service-binding callers of qnfo-ops first: a caller that retries a 503 without a delay would amplify the load, so the refusal must carry Retry-After. Work claim: file:qnfo-ops/worker.js was held by C-ops-tools when this was written; take it over when it lapses. Prediction: during the next D1 overload window the D1-writing tool calls that fail partway fall to 0 and the refusals are visible as one counted class. Closing marker: the change carries the text OPS-DEGRADED-1.' || char(10) ||
 'code-task: repo=qnfo-workers path=qnfo-ops/worker.js' || char(10) ||
 'code-anchor: async function execTool(env, name, rawArgs, userText, resultCap) {' || char(10) ||
 'code-probe: {"paths":["qnfo-ops/worker.js"],"contains":"OPS-DEGRADED-1"}',
 'session:c5-resilience', 'code', 'medium', 'open', unixepoch() * 1000, unixepoch() * 1000
WHERE NOT EXISTS (SELECT 1 FROM agent_issues WHERE instr(title, 'ROADMAP-1: QNFO.OPS OPS-DEGRADED-1:') = 1 AND status = 'open');

UPDATE roadmap_implementation
SET evidence = evidence || ' || C5-RESILIENCE-5 2026-11-05: partial. BUILT in the c5-resilience ops-failover pull request: the failover hostname is now measured. Read live 2026-11-05 ~00:00Z: https://ops.qnfo.org and https://qnfo-ops.q08.workers.dev both answer /health (200, worker qnfo-ops, version 2.63.0-tool-arg-alias, 190 ms and 140 ms) and /v1/models (200, id ops); scripts/bp26_opsfailover.py reads both hourly from the GitHub runner and writes metric ops_gateway_hosts_ok (target 1, trigger < 1, cause heartbeat). /health and /v1/models read no D1, so that part of the gateway already answers while qnfo-audit is overloaded. REMAINING: the read-only degraded mode of qnfo-ops itself (circuit breaker, 503 with Retry-After on D1-writing tools, degraded block on /health): filed as ROADMAP-1 OPS-DEGRADED-1 with code-task, anchor and probe; and the spof_registry row plus enabled spof_alternate_probes row for the gateway host, which a follow-up migration adds after the first runner reading. Live reading of ops_gateway_hosts_ok pending the first runner pass after merge.'
WHERE id = 5 AND item = 'RM-S1-REDUNDANCY-1' AND instr(evidence, 'C5-RESILIENCE-5') = 0;
